import { tags } from "typia";

/**
 * Seller dashboard summary containing aggregated performance metrics including total products, total order items, pending cancellations, and pending refunds.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEcommerceMallSellerDashboardSummary = {
  /**
   * Total number of active products listed by the seller on the platform.
   *
   * @x-autobe-specification COUNT(*) FROM ecommerce_mall_products WHERE ecommerce_mall_seller_id = :sellerId AND deleted_at IS NULL. Returns 0 when seller has no products.
   */
  products_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total number of order items across all orders containing the seller's products with status paid, shipped, or delivered.
   *
   * @x-autobe-specification COUNT(*) FROM ecommerce_mall_order_items oi JOIN ecommerce_mall_products p ON oi.ecommerce_mall_product_id = p.id WHERE p.ecommerce_mall_seller_id = :sellerId AND oi.status IN ('paid', 'shipped', 'delivered'). Returns 0 when no qualifying order items exist.
   */
  order_items_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of pending cancellation requests awaiting seller approval or rejection.
   *
   * @x-autobe-specification COUNT(*) FROM ecommerce_mall_cancellation_requests WHERE ecommerce_mall_seller_id = :sellerId AND status = 'pending'. Returns 0 when no pending cancellation requests exist.
   */
  pending_cancellations_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of pending refund requests awaiting seller response.
   *
   * @x-autobe-specification COUNT(*) FROM ecommerce_mall_refund_requests WHERE ecommerce_mall_seller_id = :sellerId AND status = 'pending'. Returns 0 when no pending refund requests exist.
   */
  pending_refunds_count: number & tags.Type<"int32"> & tags.Minimum<0>;
};
